    fun generateFakeOutfitCombinations(): List<OutfitCombination> {
        return listOf(
            OutfitCombination(shirtIndex = 0, pantIndex = 0, shoeIndex = 0, avgEmbeddings = 0.85),
            OutfitCombination(shirtIndex = 1, pantIndex = 0, shoeIndex = 2, avgEmbeddings = 0.78),
            OutfitCombination(shirtIndex = 2, pantIndex = 1, shoeIndex = 1, avgEmbeddings = 0.91),
